import json
from dataclasses import dataclass
from functools import lru_cache
from pathlib import Path

DATA_FILE = Path(__file__).resolve().parent.parent / "data" / "attack_techniques.json"
UNKNOWN_TACTIC = "unknown"
UNKNOWN_TACTIC_NAME = "Unknown"


@dataclass(frozen=True)
class Tactic:
    id: str
    name: str


@dataclass(frozen=True)
class TechniqueInfo:
    name: str
    tactics: tuple[str, ...]


@dataclass(frozen=True)
class AttackTable:
    """ATT&CK technique ids to names and tactics; generated by scripts/build-attack-table.py."""

    version: str
    modified: str
    tactics: tuple[Tactic, ...]
    techniques: dict[str, TechniqueInfo]

    @classmethod
    def from_file(cls, path: Path) -> "AttackTable":
        raw = json.loads(path.read_text())
        return cls(
            version=raw["version"],
            modified=raw["modified"],
            tactics=tuple(Tactic(**tactic) for tactic in raw["tactics"]),
            techniques={
                technique_id: TechniqueInfo(entry["name"], tuple(entry["tactics"]))
                for technique_id, entry in raw["techniques"].items()
            },
        )

    def technique(self, technique_id: str) -> TechniqueInfo | None:
        return self.techniques.get(technique_id)

    def tactic_name(self, tactic_id: str) -> str:
        return next(
            (tactic.name for tactic in self.tactics if tactic.id == tactic_id), UNKNOWN_TACTIC_NAME
        )


@lru_cache
def load_attack_table() -> AttackTable:
    return AttackTable.from_file(DATA_FILE)
